const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());

app.get('/api/projects', (req, res) => {
  // Sample projects data
  const projects = [
    {
      id: 1,
      title: 'Project Alpha',
      description: 'A sample project description.',
      tech: ['React', 'Node.js'],
      link: 'https://example.com'
    }
  ];
  res.json({ success: true, data: projects });
});

app.post('/api/contact', (req, res) => {
  const { name, email, message } = req.body;
  if (!name || name.length < 2) return res.status(400).json({ success: false, error: 'Validation failed', details: ['name is required'] });
  if (!email || !email.includes('@')) return res.status(400).json({ success: false, error: 'Validation failed', details: ['email is required', 'email is invalid'] });
  if (!message || message.length < 10) return res.status(400).json({ success: false, error: 'Validation failed', details: ['message is required', 'message is too short'] });
  res.json({ success: true, message: 'Message sent successfully' });
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

